--region 状态-神威-教学楼
---@class XKamuiTeachingBuildingState: XEcologyConstructAIBaseState
local XKamuiTeachingBuildingState = XClass(BaseState, "XKamuiTeachingBuildingState")

---数据配置
---@overload
function XKamuiTeachingBuildingState:InitStateConfig()
    self.StateConfig = {}
    self.StateConfig.StateEnum = StateEnum.TeachingBuilding
    self.StateConfig.StateAnim = "Drama_Stand_05"
    self.StateConfig.TriggerId = 1
    self.StateConfig.ShowOptionId = 1
    self.StateConfig.RegisterWorldEventList = {
        EWorldEvent.ActorTrigger,
        EWorldEvent.NpcInteractStart,
        EWorldEvent.NpcInteractComplete,
        EWorldEvent.DramaFinish,
    }
end

function XKamuiTeachingBuildingState:OnStateEnter(lastStateEnum)
    BaseState.OnStateEnter(self, lastStateEnum)
    self.StateMachine:SetDataBoard(DataBoardKey.TeachingBuilding, 0)
end

function XKamuiTeachingBuildingState:HandleEvent(eventType, eventArgs)
    BaseState.HandleEvent(self, eventType, eventArgs)
    if eventType == EWorldEvent.DramaFinish and eventArgs.DramaName == "Drama_3016_004" then
        if not eventArgs.HistoryDecisionDict[6] then
            return
        end
        if table.contains(eventArgs.HistoryDecisionDict[6], 1) then
            self.StateMachine:SetDataBoard(DataBoardKey.TeachingBuilding, 1) ----去往教室
        elseif table.contains(eventArgs.HistoryDecisionDict[6], 2) then
            self.StateMachine:SetDataBoard(DataBoardKey.TeachingBuilding, 2) ---去往训练室
        end
    end
end

--endregion


