--region 神威法奥斯生态AI
---@class XCharKamuiEcology : XEcologyConstructAIBase
---@field _stateMachine XStateMachineController 状态机
local XCharKamuiEcology = XDlcScriptManager.RegCharScript(10610501, "XCharKamuiEcology", Base)

--- 注册状态机状态
function XCharKamuiEcology:RegisterMachineState()
    self._stateMachine:AddState(StateEnum.TeachingBuilding, XKamuiTeachingBuildingState.New(self._proxy))
    self._stateMachine:AddState(StateEnum.TrainingRoom, XKamuiTrainingRoomState.New(self._proxy))
    self._stateMachine:AddState(StateEnum.Tombstone, XKamuiTombstoneState.New(self._proxy))
    self._stateMachine:AddState(StateEnum.InClass, XKamuiInClassState.New(self._proxy))
    self._stateMachine:AddState(StateEnum.Stall, XKamuiStallState.New(self._proxy))
    self._stateMachine:AddState(StateEnum.FindPath, XKamuiFindPathState.New(self._proxy))
end

--- 注册状态转移方程
function XCharKamuiEcology:RegisterMachineStateTransition()
    -- 设置寻路状态枚举值
    self.FindPathStateEnum = StateEnum.FindPath
    self.NextStateList = {
        StateEnum.TeachingBuilding, StateEnum.Tombstone, StateEnum.Stall
    }
    self.NextStateRotDict ={
        [StateEnum.TeachingBuilding] = {x=0, y=-114.512, z=0},
        [StateEnum.Tombstone] = {x=0, y=-106.342, z=0},
        [StateEnum.Stall] = {x=0, y=144.786, z=0},
    }
    -- 其他状态到寻路状态
    self:RegisterInFindPathStateTransition(StateEnum.TeachingBuilding, function()
        if self._stateMachine:CheckDataBoard(DataBoardKey.TeachingBuilding, 1) then
            return StateEnum.InClass
        elseif self._stateMachine:CheckDataBoard(DataBoardKey.TeachingBuilding, 2) then
            return StateEnum.TrainingRoom
        else
            return StateEnum.Tombstone
        end
    end, 30, 1)
    self:RegisterInFindPathStateTransition(StateEnum.TrainingRoom, function()
        return self._stateMachine:CheckDataBoard(DataBoardKey.TrainingRoom, 1) and StateEnum.Stall or StateEnum.Stall
    end, 30, 1)
    self:RegisterInFindPathStateTransition(StateEnum.Tombstone, function()
        return self._stateMachine:CheckDataBoard(DataBoardKey.Tombstone, 1) and StateEnum.Stall or StateEnum.Stall
    end, 20, 1)
    self:RegisterInFindPathStateTransition(StateEnum.Stall, function()
        return self._stateMachine:CheckDataBoard(DataBoardKey.Stall, 1) and StateEnum.TeachingBuilding or StateEnum.Tombstone
    end, 20, 1)
    self:RegisterInFindPathStateTransition(StateEnum.InClass, function()
        return self._stateMachine:CheckDataBoard(DataBoardKey.InClass, 1) and StateEnum.Stall or StateEnum.Stall
    end, 20, 1)


    -- 寻路状态到其他状态
    self:RegisterOutFindPathStateTransition(StateEnum.TeachingBuilding)
    self:RegisterOutFindPathStateTransition(StateEnum.TrainingRoom)
    self:RegisterOutFindPathStateTransition(StateEnum.Tombstone)
    self:RegisterOutFindPathStateTransition(StateEnum.InClass)
    self:RegisterOutFindPathStateTransition(StateEnum.Stall)
end

return XCharKamuiEcology
--endregion
